const alexa={name:'AleXa',sub:'SOLO ARTIST / K-POP',bio:'AleXa made her solo debut with “Bomb” in 2019 and won American Song Contest with “Wonderland” in 2022. The English-language “Juliet” turns toward intimate storytelling and a more vulnerable vocal performance, with Korean and Spanish versions extending the song into different settings.',facts:[['DEBUT','Bomb / 2019'],['RELEASE','Juliet / June 2023'],['WITH LOTUS','Production · Arrangement · Lyrics · Composition']],sources:[['JULIET · OFFICIAL','https://www.alexazb.com/juliet'],['ARTIST INTERVIEW','https://www.allkpop.com/article/2023/06/interview-alexa-delves-into-her-latest-single-juliet-her-favorite-among-all-the-versions-and-the-creative-process-behind-it']]};
